<?php
declare(strict_types=1);
require_once __DIR__.'/commissions.php';
function linkFor(array $u,string $id,bool $own=false):array{$p=record($u['tenant'],'links',$id);if(!$p||!visibleLink($u,$p)||$own&&$p['personId']!==$u['person'])throw new Fault('Matrícula não encontrada neste acesso.',404);return $p;}
function reviewerAllowed(array $u,array $a,array $p):bool{if(!$a['active']||$a['start']>today()||$a['end']<today()||$a['plan']!==$p['planId']||$a['unit']!==$p['unitId']||($a['lotation']??'')&&$a['lotation']!==$p['lotation'])return false;$member=null;foreach($a['members'] as $m){if($m['personId']===$p['personId']||$m['admission']>=$p['admission'])return false;if(commissionMemberMatches($u,$m))$member=$m;}return (bool)$member;}
function updateLink(array $u,array $p,int $version,string $action):array{$p=save($u['tenant'],'links',$p,$version);audit($u['tenant'],$action,$p['id']);return $p;}
function newProcess(array &$p,array $b):array{foreach($p['processes'] as $x)if($x['state']==='Em análise')throw new Fault('Já existe processo em análise nesta matrícula.');$x=['id'=>uid(),'type'=>need($b['type']??'','modalidade',80),'start'=>day($b['start']??''),'end'=>day($b['end']??''),'fromLevel'=>$p['level'],'fromStage'=>$p['stage'],'targetLevel'=>need($b['targetLevel']??'','nível proposto',15),'targetStage'=>need($b['targetStage']??'','referência proposta',15),'basis'=>need($b['basis']??'','fundamento',1000),'state'=>'Em análise','createdAt'=>date(DATE_ATOM)];if(!in_array($x['type'],['Progressão horizontal','Promoção vertical','Evolução por tempo de serviço'])||$x['end']<$x['start']||$x['start']<$p['admission']||$x['targetLevel']===$p['level']&&$x['targetStage']===$p['stage'])throw new Fault('Confira modalidade, período e destino.');array_unshift($p['processes'],$x);return $x;}
function event(array &$p,array $u,string $title,string $detail):void{array_unshift($p['events'],['date'=>date(DATE_ATOM),'title'=>$title,'detail'=>$detail,'actor'=>$u['id']]);}
function percentage($value):int{$v=str_replace(',','.',trim((string)$value));if(!preg_match('/^\d{1,3}(\.\d{1,4})?$/',$v)||(float)$v>100)throw new Fault('Percentual inválido; utilize até quatro casas decimais.');return (int)round((float)$v*10000);}
function cents($value):int{$v=str_replace(',','.',trim((string)$value));if(!preg_match('/^\d{1,10}(\.\d{1,2})?$/',$v))throw new Fault('Valor monetário inválido. Não use separador de milhar.');return (int)round((float)$v*100);}
function roundRate(int $c,int $rate):int{return intdiv($c*$rate+500000,1000000);}
function salaryCatalog():array{static $c;return $c??=json_decode((string)file_get_contents(TR_RELEASE.'/data/salary/catalogue.json'),true);}
function salaryCell(string $source,string $group,int $index):array{$s=null;$g=null;foreach(salaryCatalog()['sources'] as $x)if($x['id']===$source)$s=$x;foreach($s['jobs']??[] as $x)if($x['id']===$group)$g=$x;if(!$g||$index<0)throw new Fault('Referência salarial inválida.');$data=json_decode((string)file_get_contents(TR_RELEASE.'/data/salary/'.basename($g['data'])),true);$row=$data['rows'][$index]??null;if(!$row)throw new Fault('Célula salarial não encontrada.');$money=array_search('money',array_column($s['columns'],'type'),true);return ['cents'=>$row[$money],'row'=>$row,'source'=>$s,'group'=>$g];}
function salaryContextKey(array $p):string{return j([$p['planId'],$p['role'],$p['workload'],$p['level'],$p['stage']]);}
function salaryQuote(string $tenant,?array $map,array $p,string $at,?array $process=null):array{if(!$map)throw new Fault($process?'Destino salarial não vinculado.':'Salário atual não vinculado.');$job=record($tenant,'salary_jobs',$map['jobId']);$frame=$job?record($tenant,'salary_frames',$job['frame']):null;if(!$frame||$frame['plan']!==$p['planId']||!in_array($map['groupId'],$job['groups']['ids'],true)||$map['context']!==salaryContextKey($p)||$job['workload']&&(float)$job['workload']!==(float)$p['workload'])throw new Fault('Cargo, jornada ou enquadramento mudou. Revalide a vinculação salarial.');if($process&&($map['target']??'')!==j([$process['id'],$process['targetLevel'],$process['targetStage'],$process['type']]))throw new Fault('Destino do processo alterado.');$cell=salaryCell($job['source'],$map['groupId'],(int)$map['rowIndex']);if($job['source_hash']!==$cell['source']['sha256']||$at<$job['base_from'])throw new Fault('Fonte salarial ou vigência incompatível.');$value=$cell['cents'];$changes=records($tenant,'salary_changes');usort($changes,fn($a,$b)=>[$a['effective'],$a['sequence']]<=>[$b['effective'],$b['sequence']]);foreach($changes as $e)if($e['frame']===$frame['id']&&$e['effective']>=$job['base_from']&&$e['effective']<=$at&&$e['sequence']>($job['groups']['baseSequence']??0)&&($e['kind']==='annual'||$e['job']===$job['id']))$value=roundRate($value,1000000+$e['rate']);return ['cents'=>$value,'jobId'=>$job['id'],'frameId'=>$frame['id'],'frameVersion'=>$frame['version'],'cargo'=>$job['name'],'reference'=>$map['groupId'].' / '.implode(' / ',array_slice($cell['row'],0,3)),'sourceHash'=>$job['source_hash'],'law'=>$job['law']];}
function paidPay(int $basic,array $p,string $at):array{$active=array_values(array_filter($p['paidFunctions']??[],fn($a)=>$a['start']<=$at&&(!$a['end']||$a['end']>=$at)));if(count($active)>1)throw new Fault('Funções remuneradas sobrepostas; confira a cumulatividade.');$f=$active[0]['snapshot']??null;$amount=0;$total=$basic;$treatment='Sem função remunerada';if($f){if($f['from']>$at||($f['until']??null)&&$f['until']<$at)throw new Fault('Função sem valor vigente.');if($f['mode']==='percentage'){$amount=roundRate($f['basis']==='basic'?$basic:$f['basisCents'],$f['rate']);$total+=$amount;$treatment='Gratificação percentual adicional';}else{$amount=$f['amount'];$total=$f['treatment']==='replacement'?$amount:$basic+$amount;$treatment=$f['treatment']==='replacement'?'Remuneração substitutiva da função':'Gratificação fixa adicional';}}return ['basicCents'=>$basic,'functionCents'=>$amount,'totalCents'=>$total,'treatment'=>$treatment];}
function forecast(string $tenant,array $p,?array $process,string $effect):array{$row=['linkId'=>$p['id'],'registration'=>$p['registration'],'name'=>$p['name'],'role'=>$p['role']];try{$current=salaryQuote($tenant,$p['salary']??null,$p,today());$baseline=salaryQuote($tenant,$p['salary']??null,$p,$effect);$target=salaryQuote($tenant,$process['salaryTarget']??null,$p,$effect,$process);$cp=paidPay($current['cents'],$p,today());$bp=paidPay($baseline['cents'],$p,$effect);$tp=paidPay($target['cents'],$p,$effect);return $row+['currentCents'=>$cp['totalCents'],'currentBasicCents'=>$cp['basicCents'],'currentFunctionCents'=>$cp['functionCents'],'baselineEffectCents'=>$bp['totalCents'],'targetCents'=>$tp['totalCents'],'targetBasicCents'=>$tp['basicCents'],'targetFunctionCents'=>$tp['functionCents'],'promotionDeltaCents'=>$tp['totalCents']-$bp['totalCents'],'totalDeltaCents'=>$tp['totalCents']-$cp['totalCents'],'functionTreatment'=>$tp['treatment'],'effect'=>$effect,'current'=>$current,'target'=>$target];}catch(Fault $e){return $row+['error'=>$e->getMessage()];}}
function certificateStatus(array $c):string{foreach($c['votes'] as $v)if($v['decision']==='Rejeitar')return 'Rejeitado';return count($c['votes'])===count($c['reviewers'])?'Aprovado':'Em análise';}
function eligibleProof(string $tenant,array $p,array $process,int $cycle):array{$cutoff=$cycle.'-06-30';$used=[];foreach(records($tenant,'eligibility') as $e)if($e['link']===$p['id']&&($e['batch']??null))foreach($e['evidence'] as $c)$used[]=$c['id'];return array_values(array_filter(records($tenant,'certificates'),fn($c)=>$c['link']===$p['id']&&certificateStatus($c)==='Aprovado'&&$c['createdDay']<=$cutoff&&$c['completed']<=$cutoff&&$c['completed']>=$process['start']&&$c['completed']<=$process['end']&&!in_array($c['id'],$used,true)&&(($c['kind']==='Capacitação'&&$process['type']==='Progressão horizontal')||($c['kind']==='Titulação'&&$process['type']==='Promoção vertical'&&$c['targetLevel']===$process['targetLevel']))));}
function rankAnnual(array $u,string $plan,int $cycle,array $criteria):array{$pl=record($u['tenant'],'plans',$plan);if(($pl['family']??'')!=='geral')throw new Fault('Este ciclo é exclusivo do Quadro Geral.');if(!$criteria||count($criteria)!==count(array_unique($criteria))||array_diff($criteria,['service','performance','hours']))throw new Fault('Critérios de classificação inválidos.');$rows=[];foreach(records($u['tenant'],'eligibility') as $e){$p=record($u['tenant'],'links',$e['link']);if(($e['batch']??null)||$e['cycle']!==$cycle||!$p||$p['planId']!==$plan)continue;if($p['version']!==$e['linkVersion'])throw new Fault('Uma matrícula foi alterada. Refaça a habilitação.',409);$proc=null;foreach($p['processes'] as $x)if($x['id']===$e['process'])$proc=$x;if(!$proc||$proc['state']!=='Em análise')throw new Fault('Processo alterado.',409);$proof=eligibleProof($u['tenant'],$p,$proc,$cycle);if(j($proof)!==j($e['evidence']))throw new Fault('Evidências alteradas. Refaça a habilitação.',409);$service=(int)(new DateTimeImmutable($p['admission']))->diff(new DateTimeImmutable($cycle.'-06-30'))->days;$values=[];foreach($criteria as $c)$values[]=$c==='service'?$service:($c==='performance'?($p['evaluations'][0]['score']??null):array_sum(array_column($proof,'hours')));if(in_array(null,$values,true))throw new Fault('Há candidato sem valor para um critério.');$rows[]=['id'=>$e['id'],'link'=>$p['id'],'role'=>$p['role'],'group'=>$p['role'],'name'=>$p['name'],'registration'=>$p['registration'],'values'=>$values,'from'=>$p['level'].' / '.$p['stage'],'target'=>$proc['targetLevel'].' / '.$proc['targetStage'],'evidence'=>$proof,'process'=>$proc['id']];}usort($rows,function($a,$b){$r=strcmp($a['role'],$b['role']);if($r)return $r;foreach($a['values'] as $i=>$v){$r=$b['values'][$i]<=>$v;if($r)return $r;}return strcmp($a['id'],$b['id']);});$group='';$n=0;foreach($rows as $i=>&$r){if($group!==$r['group']){$n=0;$group=$r['group'];}$r['position']=++$n;$r['tie']=($i>0&&$rows[$i-1]['group']===$r['group']&&$rows[$i-1]['values']===$r['values'])||isset($rows[$i+1])&&$rows[$i+1]['group']===$r['group']&&$rows[$i+1]['values']===$r['values'];}unset($r);return $rows;}
function validateSelection(array $rows,array $ids):array{if(!$ids||count($ids)!==count(array_unique($ids))||array_diff($ids,array_column($rows,'id')))throw new Fault('Seleção inválida ou vazia.');$omitted=[];foreach($rows as $r){if(!in_array($r['id'],$ids,true)){$omitted[]=$r;continue;}foreach($rows as $prior)if($prior['group']===$r['group']&&!in_array($prior['id'],$ids,true)&&($prior['position']<$r['position']||$prior['values']===$r['values']))throw new Fault('Não é permitido preterir candidato anterior ou separar empate no corte.');}return $omitted;}
function annualBudget(array $u,array $ids,array $o,array $options):array{$rows=[];foreach($ids as $id){$e=record($u['tenant'],'eligibility',$id);$p=$e?record($u['tenant'],'links',$e['link']):null;if(!$e||!$p||($e['batch']??null)||$e['cycle']!==$o['cycle']||$p['planId']!==$o['plan']||$p['version']!==$e['linkVersion'])throw new Fault('Habilitação alterada.',409);$proc=null;foreach($p['processes'] as $x)if($x['id']===$e['process'])$proc=$x;$rows[]=forecast($u['tenant'],$p,$proc,$o['effect']);}$missing=count(array_filter($rows,fn($r)=>isset($r['error'])));$months=($options['months']??'')!==''?(float)$options['months']:(str_ends_with($o['effect'],'-01')?13-(int)substr($o['effect'],5,2):-1);num($months,0,12,'meses do exercício');$monthly=$missing?null:array_sum(array_column($rows,'promotionDeltaCents'));$exercise=$missing?null:(int)round($monthly*$months);$rate=($options['chargesPct']??'')===''?null:percentage($options['chargesPct']);$other=($options['otherAnnual']??'')===''?null:cents($options['otherAnnual']);$charges=$rate===null||$missing?null:(int)round($exercise*$rate/1000000);$r=['complete'=>!$missing,'count'=>count($rows),'pending'=>$missing,'rows'=>$rows,'months'=>$months,'monthlyCents'=>$monthly,'exerciseCents'=>$exercise,'chargesRate'=>$rate,'chargesCents'=>$charges,'otherAnnualCents'=>$other,'estimatedCents'=>$missing?null:$exercise+($charges??0)+($other??0),'effect'=>$o['effect'],'coverage'=>'Vencimento e função vinculada; encargos e provisões somente quando parametrizados.'];$r['token']=hash_hmac('sha256',j([$u['tenant'],$ids,$o['id'],$r]),config()['key']);return $r;}
